app.post('/api/tuckquest/drivers',current,asyncRoute(async(req:any,res:any)=>{const input=z.object({address:z.string().min(5),licenceNumber:z.string().min(3),licenceExpiry:z.string().datetime(),vehicleMake:z.string().min(2),vehicleModel:z.string().min(1),registration:z.string().min(3),vehicleType:z.string().min(2),vehicleColour:z.string().min(2),vehiclePhotoUrl:z.string().url().optional(),documentRefs:z.string().optional(),paymentProfileRef:z.string().optional()}).parse(req.body);const data={...input,licenceExpiry:new Date(input.licenceExpiry),verificationStatus:'PENDING' as const};const profile=await db.driverProfile.upsert({where:{userId:req.identity.sub},update:data,create:{...data,userId:req.identity.sub}});res.status(201).json({profile});}));
app.patch('/api/tuckquest/drivers/me/location',current,asyncRoute(async(req:any,res:any)=>{const input=z.object({isOnline:z.boolean(),latitude:z.number().min(-90).max(90).optional(),longitude:z.number().min(-180).max(180).optional()}).parse(req.body);const profile=await db.driverProfile.findUniqueOrThrow({where:{userId:req.identity.sub}});if(input.isOnline&&profile.verificationStatus!=='VERIFIED')return res.status(403).json({error:'Only verified drivers may go online'});res.json({profile:await db.driverProfile.update({where:{userId:req.identity.sub},data:input})});}));
