app.post('/api/tuckquest/requests/:id/prices',current,asyncRoute(async(req:any,res:any)=>{const input=purchaseUpdateSchema.parse(req.body);const request=await ownDriverRequest(req.params.id,req.identity.sub);assertTransition(request.status,'AWAITING_APPROVAL');const itemMap=new Map(request.items.map(item=>[item.id,item]));let actualTotalCents=0;await db.$transaction(async tx=>{for(const change of input.items){const item=itemMap.get(change.id);if(!item)throw Object.assign(new Error('Item does not belong to request'),{status:400});await tx.stockRequestItem.update({where:{id:item.id},data:change});if(!change.unavailable)actualTotalCents+=(change.actualUnitCents??0)*item.quantity}await tx.stockRequest.update({where:{id:request.id},data:{receiptUrl:input.receiptUrl,actualTotalCents,status:'AWAITING_APPROVAL'}})});res.json({request:await db.stockRequest.findUnique({where:{id:request.id},include:{items:true}})});}));
