app.post('/api/tuckquest/requests/:id/delivering',current,asyncRoute(async(req:any,res:any)=>{const request=await ownDriverRequest(req.params.id,req.identity.sub);assertTransition(request.status,'DELIVERING');const pin=String(Math.floor(100000+Math.random()*900000));res.json({request:await db.stockRequest.update({where:{id:request.id},data:{status:'DELIVERING',deliveryPinHash:await hashPassword(pin)}}),deliveryPin:pin});}));
