app.post('/api/tuckquest/requests/:id/confirm',current,asyncRoute(async(req:any,res:any)=>{const {pin}=z.object({pin:z.string().length(6)}).parse(req.body);const request=await ownBusinessRequest(req.params.id,req.identity.sub);assertTransition(request.status,'DELIVERED');if(!request.deliveryPinHash||!await verifyPassword(pin,request.deliveryPinHash))return res.status(400).json({error:'Invalid delivery PIN'});const delivered=await db.$transaction(async tx=>{const updated=await tx.stockRequest.update({where:{id:request.id},data:{status:'DELIVERED',deliveryPinHash:null}});for(const item of request.items){if(item.unavailable)continue;const product=await tx.product.findFirst({where:{businessId:request.businessId,name:item.productName}});if(product)await tx.inventoryMovement.create({data:{productId:product.id,type:'PURCHASE',quantityDelta:item.quantity,unitCostCents:item.actualUnitCents,reference:request.receiptUrl,sourceRequestId:request.id}})}await tx.expense.create({data:{businessId:request.businessId,category:'STOCK_PURCHASE',supplier:request.supplierName,amountCents:request.actualTotalCents??request.estimatedTotalCents,reference:request.receiptUrl}});await tx.supplierOrder.updateMany({where:{stockRequestId:request.id},data:{status:'DELIVERED'}});return updated});res.json({request:delivered});}));
app.post('/api/tuckquest/requests/:id/reviews',current,asyncRoute(async(req:any,res:any)=>{const input=z.object({subjectId:z.string(),rating:z.number().int().min(1).max(5),comment:z.string().max(500).optional()}).parse(req.body);const request=await db.stockRequest.findUniqueOrThrow({where:{id:req.params.id},include:{business:{include:{members:true}}}});if(request.status!=='DELIVERED')return res.status(409).json({error:'Only delivered requests may be reviewed'});if(!(request.driverId===req.identity.sub||request.business.members.some(member=>member.userId===req.identity.sub)))return res.status(403).json({error:'Only transaction participants may review'});res.status(201).json({review:await db.review.create({data:{requestId:request.id,authorId:req.identity.sub,subjectId:input.subjectId,rating:input.rating,comment:input.comment}})});}));
app.get('/api/shop/:slug',asyncRoute(async(req:any,res:any)=>{const business=await db.business.findFirst({where:{storefrontSlug:req.params.slug,storefrontPublished:true},select:{name:true,storefrontSlug:true,logoUrl:true,publicDescription:true,openingHours:true,serviceArea:true,publicPhone:true,publicEmail:true,whatsappNumber:true,orderUrl:true,products:{where:{storefrontVisible:true},select:{id:true,name:true,category:true,sellingPriceCents:true,publicDescription:true,imageUrl:true},orderBy:{name:'asc'}}}});if(!business)return res.status(404).json({error:'Storefront not found'});res.set('Cache-Control','public, max-age=60, stale-while-revalidate=300').json({storefront:{slug:business.storefrontSlug,name:business.name,logoUrl:business.logoUrl,description:business.publicDescription,openingHours:business.openingHours,serviceArea:business.serviceArea,contact:{phone:business.publicPhone,email:business.publicEmail,whatsapp:business.whatsappNumber,orderUrl:business.orderUrl},products:business.products.map(publicProduct)}});}));
