app.put('/api/kasibiz/storefront/:businessId',current,asyncRoute(async(req:any,res:any)=>{await requireBusiness(req.params.businessId,req.identity.sub);const input=storefrontSchema.parse(req.body),data={storefrontSlug:input.slug,storefrontPublished:input.published,logoUrl:input.logoUrl||null,publicDescription:input.description,openingHours:input.openingHours,serviceArea:input.serviceArea,publicPhone:input.publicPhone||null,publicEmail:input.publicEmail||null,whatsappNumber:input.whatsappNumber||null,orderUrl:input.orderUrl||null},business=await db.$transaction(async tx=>{const updated=await tx.business.update({where:{id:req.params.businessId},data});await tx.auditLog.create({data:{action:input.published?'STOREFRONT_PUBLISHED':'STOREFRONT_UPDATED',entity:'Business',entityId:updated.id,userId:req.identity.sub,metadata:JSON.stringify({slug:input.slug,published:input.published})}});return updated}),origin=process.env.PUBLIC_APP_URL||`${req.protocol}://${req.get('host')}`,url=storefrontUrl(origin,input.slug);res.json({business,url,qrCodeUrl:qrCodeUrl(url)});}));
