app.post('/api/kasibiz/products',current,asyncRoute(async(req:any,res:any)=>{const input=productSchema.parse(req.body);await requireBusiness(input.businessId,req.identity.sub);const subscription=await db.ecosystemSubscription.findFirst({where:{businessId:input.businessId,status:'ACTIVE',OR:[{currentPeriodTo:null},{currentPeriodTo:{gt:new Date()}}]},orderBy:{createdAt:'desc'}});if(subscription&&!featureEnabled(subscription.featuresSnapshot,'inventory'))return res.status(403).json({error:'Your subscription does not include inventory'});const limit=subscription?planLimit(subscription.limitsSnapshot,'products'):0;if(limit&&await db.product.count({where:{businessId:input.businessId}})>=limit)return res.status(409).json({error:'Product limit reached for this subscription'});const {openingQuantity,...data}=input;const product=await db.$transaction(async tx=>{const created=await tx.product.create({data});if(openingQuantity)await tx.inventoryMovement.create({data:{productId:created.id,type:'ADJUSTMENT',quantityDelta:openingQuantity,reference:'OPENING_STOCK'}});return created});res.status(201).json({product});}));
app.get('/api/kasibiz/products/:businessId',current,asyncRoute(async(req:any,res:any)=>{await requireBusiness(req.params.businessId,req.identity.sub);const products=await db.product.findMany({where:{businessId:req.params.businessId},include:{movements:true}});res.json({products:products.map(product=>({...product,quantity:currentStock(product.movements)}))});}));
app.post('/api/kasibiz/sales',current,asyncRoute(async(req:any,res:any)=>{const input=saleSchema.parse(req.body);await requireBusiness(input.businessId,req.identity.sub);const products=await db.product.findMany({where:{id:{in:input.items.map(item=>item.productId)},businessId:input.businessId},include:{movements:true}});if(products.length!==new Set(input.items.map(item=>item.productId)).size)return res.status(400).json({error:'One or more products are invalid'});const lines=input.items.map(item=>{const product=products.find(p=>p.id===item.productId)!;if(currentStock(product.movements)<item.quantity)throw Object.assign(new Error(`Insufficient stock for ${product.name}`),{status:409});return{...item,unitPriceCents:product.sellingPriceCents}});const totals=saleTotals(lines,input.discountCents);const sale=await db.$transaction(async tx=>{const created=await tx.sale.create({data:{businessId:input.businessId,paymentMethod:input.paymentMethod,...totals,items:{create:lines.map(line=>({productId:line.productId,quantity:line.quantity,unitPriceCents:line.unitPriceCents}))}}});for(const line of lines)await tx.inventoryMovement.create({data:{productId:line.productId,type:'SALE',quantityDelta:-line.quantity,reference:created.id}});return created});res.status(201).json({sale});}));
app.post('/api/kasibiz/sales/:id/refund',current,asyncRoute(async(req:any,res:any)=>{const sale=await db.sale.findUniqueOrThrow({where:{id:req.params.id},include:{items:true}});await requireBusiness(sale.businessId,req.identity.sub);if(sale.refundedAt)return res.status(409).json({error:'Sale already refunded'});await db.$transaction(async tx=>{await tx.sale.update({where:{id:sale.id},data:{refundedAt:new Date()}});for(const item of sale.items)await tx.inventoryMovement.create({data:{productId:item.productId,type:'RETURN',quantityDelta:item.quantity,reference:sale.id}})});res.status(204).end();}));
app.get('/api/kasibiz/dashboard/:businessId',current,asyncRoute(async(req:any,res:any)=>{await requireBusiness(req.params.businessId,req.identity.sub);const now=new Date(),monthStart=new Date(now.getFullYear(),now.getMonth(),1),dayStart=new Date(now.getFullYear(),now.getMonth(),now.getDate());const [sales,expenses,products]=await Promise.all([db.sale.findMany({where:{businessId:req.params.businessId,refundedAt:null,createdAt:{gte:monthStart}}}),db.expense.findMany({where:{businessId:req.params.businessId,createdAt:{gte:monthStart}}}),db.product.findMany({where:{businessId:req.params.businessId},include:{movements:true}})]);const monthSales=sales.reduce((s,x)=>s+x.totalCents,0),expenseTotal=expenses.reduce((s,x)=>s+x.amountCents,0);res.json({todaySales:sales.filter(s=>s.createdAt>=dayStart).reduce((n,s)=>n+s.totalCents,0),monthSales,expenses:expenseTotal,estimatedProfit:monthSales-expenseTotal,lowStock:products.filter(p=>currentStock(p.movements)<=p.reorderLevel).map(p=>({...p,quantity:currentStock(p.movements)}))});}));
app.post('/api/kasibiz/low-stock/:businessId/order',current,asyncRoute(async(req:any,res:any)=>{await requireBusiness(req.params.businessId,req.identity.sub);const input=z.object({supplierName:z.string().min(2),deliveryAddress:z.string().min(5)}).parse(req.body);const products=await db.product.findMany({where:{businessId:req.params.businessId},include:{movements:true}});const low=products.filter(p=>currentStock(p.movements)<=p.reorderLevel);if(!low.length)return res.status(409).json({error:'No products are at reorder level'});const request=await db.stockRequest.create({data:{businessId:req.params.businessId,supplierName:input.supplierName,deliveryAddress:input.deliveryAddress,status:'SEARCHING_DRIVER',estimatedTotalCents:low.reduce((s,p)=>s+Math.max(1,p.reorderLevel*2-currentStock(p.movements))*p.costPriceCents,0),items:{create:low.map(p=>({productName:p.name,quantity:Math.max(1,p.reorderLevel*2-currentStock(p.movements)),estimatedUnitCents:p.costPriceCents}))}},include:{items:true}});res.status(201).json({request});}));
app.get('/api/wallet',current,asyncRoute(async(req:any,res:any)=>{const wallet=await db.wallet.upsert({where:{userId:req.identity.sub},update:{},create:{userId:req.identity.sub},include:{transactions:{orderBy:{createdAt:'desc'},take:100}}});const completed=wallet.transactions.filter(t=>t.status==='COMPLETED');res.json({wallet,balanceCents:completed.reduce((sum,t)=>sum+signedAmount(t.type,t.amountCents),0),availableCents:completed.filter(t=>t.type!=='HOLD').reduce((sum,t)=>sum+signedAmount(t.type,t.amountCents),0)});}));
app.post('/api/payments/initiate',current,asyncRoute(async(req:any,res:any)=>{const input=paymentRequestSchema.parse(req.body),provider=getPaymentProvider();const existing=await db.paymentRecord.findUnique({where:{idempotencyKey:input.idempotencyKey}});if(existing)return res.json({payment:existing});const initiated=await provider.initiate(input);const payment=await db.paymentRecord.create({data:{provider:provider.name,providerReference:initiated.providerReference,idempotencyKey:input.idempotencyKey,amountCents:input.amountCents,currency:input.currency,status:'PENDING',relatedEntityType:input.relatedEntityType,relatedEntityId:input.relatedEntityId,metadata:JSON.stringify({userId:req.identity.sub})}});res.status(201).json({payment});}));
app.post('/api/payments/webhooks/sandbox',asyncRoute(async(req:any,res:any)=>{const provider=getPaymentProvider(),signature=String(req.headers['x-hydra-signature']||'');if(!provider.verifyWebhook(req.rawBody||'',signature))return res.status(401).json({error:'Invalid webhook signature'});const event=z.object({providerReference:z.string(),status:z.enum(['SUCCEEDED','FAILED'])}).parse(req.body);const payment=await db.paymentRecord.findUniqueOrThrow({where:{providerReference:event.providerReference}});if(payment.status==='SUCCEEDED'||payment.status==='FAILED')return res.status(204).end();await db.$transaction(async tx=>{await tx.paymentRecord.update({where:{id:payment.id},data:{status:event.status}});if(event.status==='SUCCEEDED'){const userId=JSON.parse(payment.metadata||'{}').userId;if(!userId)throw new Error('Payment owner is missing');const wallet=await tx.wallet.upsert({where:{userId},update:{},create:{userId}});await tx.walletTransaction.create({data:{walletId:wallet.id,type:'CREDIT',amountCents:payment.amountCents,currency:payment.currency,reference:`payment:${payment.id}`,status:'COMPLETED',relatedEntityType:payment.relatedEntityType,relatedEntityId:payment.relatedEntityId}});if(payment.relatedEntityType==='HostingInvoice'&&payment.relatedEntityId){const invoice=await tx.hostingInvoice.update({where:{id:payment.relatedEntityId},data:{status:'PAID',paidAt:new Date(),paymentId:payment.id}});await tx.hostingSubscription.update({where:{id:invoice.subscriptionId},data:{status:'PROVISIONING'}});await tx.provisionJob.updateMany({where:{subscriptionId:invoice.subscriptionId,status:'PENDING_ADMIN'},data:{status:'PENDING_ADMIN'}})}if(payment.relatedEntityType==='EcosystemInvoice'&&payment.relatedEntityId){const invoice=await tx.ecosystemInvoice.update({where:{id:payment.relatedEntityId},data:{status:'PAID',paidAt:new Date(),paymentId:payment.id}});await activateEcosystemSubscription(tx,invoice.subscriptionId)}}});res.status(204).end();}));
app.post('/api/payments/:id/refund',current,asyncRoute(async(req:any,res:any)=>{const payment=await db.paymentRecord.findUniqueOrThrow({where:{id:req.params.id}});const ownerId=JSON.parse(payment.metadata||'{}').userId;if(ownerId!==req.identity.sub)return res.status(403).json({error:'Payment ownership required'});if(payment.status!=='SUCCEEDED')return res.status(409).json({error:'Only successful payments may be refunded'});const provider=getPaymentProvider();await provider.refund(payment.providerReference!,payment.amountCents);const wallet=await db.wallet.findUniqueOrThrow({where:{userId:ownerId}});const original=await db.walletTransaction.findUniqueOrThrow({where:{reference:`payment:${payment.id}`}});await db.$transaction([db.paymentRecord.update({where:{id:payment.id},data:{status:'REFUNDED'}}),db.walletTransaction.create({data:{walletId:wallet.id,type:'DEBIT',amountCents:payment.amountCents,currency:payment.currency,reference:`refund:${payment.id}`,status:'COMPLETED',reversalOfId:original.id,relatedEntityType:payment.relatedEntityType,relatedEntityId:payment.relatedEntityId}})]);res.status(202).json({status:'REFUNDED'});}));
app.put('/api/admin/commission-rules/:service',current,asyncRoute(async(req:any,res:any)=>{if(!req.identity.roles.some((r:string)=>['ADMIN','SUPER_ADMIN'].includes(r)))return res.status(403).json({error:'Administrator role required'});const input=z.object({commissionBasisPoints:z.number().int().min(0).max(10000),paymentFeeCents:z.number().int().nonnegative(),vatBasisPoints:z.number().int().min(0).max(10000)}).parse(req.body);res.json({rule:await db.commissionRule.upsert({where:{service_active:{service:req.params.service,active:true}},update:input,create:{service:req.params.service,active:true,...input}})});}));
app.post('/api/tuckquest/requests/:id/settle',current,asyncRoute(async(req:any,res:any)=>{const request=await ownBusinessRequest(req.params.id,req.identity.sub);if(request.status!=='DELIVERED'||!request.driverId)return res.status(409).json({error:'A delivered request with an assigned driver is required'});const rule=await db.commissionRule.findUnique({where:{service_active:{service:'TUCKQUEST',active:true}}});if(!rule)return res.status(409).json({error:'TUCKQUEST commission rule is not configured'});const grossCents=z.object({grossCents:z.number().int().positive()}).parse(req.body).grossCents,snapshot=calculateCommission({grossCents,commissionBasisPoints:rule.commissionBasisPoints,paymentFeeCents:rule.paymentFeeCents,vatBasisPoints:rule.vatBasisPoints});const wallet=await db.wallet.upsert({where:{userId:request.driverId},update:{},create:{userId:request.driverId}});const reference=`tuckquest-settlement:${request.id}`;const transaction=await db.walletTransaction.create({data:{walletId:wallet.id,type:'CREDIT',amountCents:snapshot.netSettlementCents,reference,status:'COMPLETED',relatedEntityType:'StockRequest',relatedEntityId:request.id,commissionSnapshot:JSON.stringify(snapshot)}});res.status(201).json({transaction,snapshot});}));
app.get('/api/tuckquest/driver/earnings',current,asyncRoute(async(req:any,res:any)=>{const wallet=await db.wallet.findUnique({where:{userId:req.identity.sub},include:{transactions:{where:{relatedEntityType:'StockRequest'},orderBy:{createdAt:'desc'}}}});const transactions=wallet?.transactions??[],now=new Date(),day=new Date(now.getFullYear(),now.getMonth(),now.getDate()),week=new Date(day);week.setDate(day.getDate()-day.getDay());const month=new Date(now.getFullYear(),now.getMonth(),1),sum=(from:Date,status='COMPLETED')=>transactions.filter(t=>t.createdAt>=from&&t.status===status).reduce((n,t)=>n+signedAmount(t.type,t.amountCents),0);res.json({today:sum(day),thisWeek:sum(week),thisMonth:sum(month),available:transactions.filter(t=>t.status==='COMPLETED').reduce((n,t)=>n+signedAmount(t.type,t.amountCents),0),pending:transactions.filter(t=>t.status==='PENDING').reduce((n,t)=>n+t.amountCents,0),transactions,withdrawalsEnabled:false});}));
