app.post('/api/mzansifix/requests/:id/quotes',current,asyncRoute(async(req:any,res:any)=>{const provider=await db.serviceProvider.findUniqueOrThrow({where:{userId:req.identity.sub}});if(provider.verificationStatus!=='VERIFIED')return res.status(403).json({error:'Verified provider profile required'});const input=quoteSchema.parse(req.body),request=await db.serviceRequest.findUniqueOrThrow({where:{id:req.params.id}});if(!['REQUESTED','QUOTED'].includes(request.status))return res.status(409).json({error:'Request is not accepting quotes'});const quote=await db.$transaction(async tx=>{const q=await tx.serviceQuote.upsert({where:{requestId_providerId:{requestId:request.id,providerId:provider.id}},update:{...input,totalCents:quoteTotal(input)},create:{...input,totalCents:quoteTotal(input),requestId:request.id,providerId:provider.id}});if(request.status==='REQUESTED'){await tx.serviceRequest.update({where:{id:request.id},data:{status:'QUOTED'}});await tx.serviceTransition.create({data:{requestId:request.id,fromState:'REQUESTED',toState:'QUOTED',actorId:req.identity.sub}})}return q});res.status(201).json({quote});}));
