app.post('/api/mzansifix/quotes/:id/accept',current,asyncRoute(async(req:any,res:any)=>{const quote=await db.serviceQuote.findUniqueOrThrow({where:{id:req.params.id},include:{request:true}});if(quote.request.customerId!==req.identity.sub)return res.status(403).json({error:'Customer ownership required'});assertServiceTransition(quote.request.status,'ACCEPTED');const wallet=await db.wallet.findUnique({where:{userId:req.identity.sub},include:{transactions:true}}),balance=(wallet?.transactions??[]).filter(t=>t.status==='COMPLETED').reduce((n,t)=>n+signedAmount(t.type,t.amountCents),0);if(!wallet||balance<quote.totalCents)return res.status(409).json({error:'Insufficient HYDRA Wallet balance'});const request=await db.$transaction(async tx=>{await tx.walletTransaction.create({data:{walletId:wallet.id,type:'HOLD',amountCents:quote.totalCents,reference:`mzansifix-hold:${quote.requestId}`,status:'PENDING',relatedEntityType:'ServiceRequest',relatedEntityId:quote.requestId}});const updated=await tx.serviceRequest.update({where:{id:quote.requestId},data:{status:'ACCEPTED',providerId:quote.providerId,acceptedQuoteId:quote.id,paymentHoldRef:`mzansifix-hold:${quote.requestId}`}});await tx.serviceTransition.create({data:{requestId:quote.requestId,fromState:quote.request.status,toState:'ACCEPTED',actorId:req.identity.sub}});return updated});res.json({request});}));
