app.post('/api/mzansifix/requests/:id/release',current,asyncRoute(async(req:any,res:any)=>{const request=await ownServiceCustomer(req.params.id,req.identity.sub);assertServiceTransition(request.status,'PAYMENT_RELEASED');if(!request.providerId||!request.acceptedQuoteId||!request.paymentHoldRef)return res.status(409).json({error:'Payment hold is incomplete'});const [quote,provider,rule]=await Promise.all([db.serviceQuote.findUniqueOrThrow({where:{id:request.acceptedQuoteId}}),db.serviceProvider.findUniqueOrThrow({where:{id:request.providerId}}),db.commissionRule.findUnique({where:{service_active:{service:'MZANSIFIX',active:true}}})]);if(!rule)return res.status(409).json({error:'MZANSIFIX commission rule is not configured'});const snapshot=calculateCommission({grossCents:quote.totalCents,commissionBasisPoints:rule.commissionBasisPoints,paymentFeeCents:rule.paymentFeeCents,vatBasisPoints:rule.vatBasisPoints}),providerWallet=await db.wallet.upsert({where:{userId:provider.userId},update:{},create:{userId:provider.userId}}),hold=await db.walletTransaction.findUniqueOrThrow({where:{reference:request.paymentHoldRef}});await db.$transaction(async tx=>{await tx.walletTransaction.update({where:{id:hold.id},data:{status:'COMPLETED',commissionSnapshot:JSON.stringify(snapshot)}});await tx.walletTransaction.create({data:{walletId:providerWallet.id,type:'CREDIT',amountCents:snapshot.netSettlementCents,reference:`mzansifix-settlement:${request.id}`,status:'COMPLETED',relatedEntityType:'ServiceRequest',relatedEntityId:request.id,commissionSnapshot:JSON.stringify(snapshot)}});await tx.serviceRequest.update({where:{id:request.id},data:{status:'PAYMENT_RELEASED'}});await tx.serviceTransition.create({data:{requestId:request.id,fromState:request.status,toState:'PAYMENT_RELEASED',actorId:req.identity.sub}})});res.json({snapshot});}));
