app.post('/api/mzansiwork/applications/:id/select',current,asyncRoute(async(req:any,res:any)=>{const application=await db.jobApplication.findUniqueOrThrow({where:{id:req.params.id},include:{job:true,worker:{include:{workerProfile:true}}}});await ownEmployerJob(application.jobId,req.identity.sub);if(!application.worker.workerProfile)return res.status(409).json({error:'Worker profile is incomplete'});const selected=await db.$transaction(async tx=>{await tx.jobApplication.update({where:{id:application.id},data:{status:'SELECTED'}});return tx.workAssignment.create({data:{jobId:application.jobId,workerId:application.worker.workerProfile!.id,status:'PENDING_ACCEPTANCE'}})});res.status(201).json({assignment:selected});}));
