app.post('/api/mzansiwork/assignments/:id/check-in',current,asyncRoute(async(req:any,res:any)=>{const assignment=await ownWorkerAssignment(req.params.id,req.identity.sub);if(!['SCHEDULED','IN_PROGRESS'].includes(assignment.status))return res.status(409).json({error:'Assignment cannot be checked into'});const location=z.object({latitude:z.number().min(-90).max(90).optional(),longitude:z.number().min(-180).max(180).optional()}).parse(req.body);const open=await db.workTimeEntry.findFirst({where:{assignmentId:assignment.id,checkedOutAt:null}});if(open)return res.status(409).json({error:'An active check-in already exists'});const entry=await db.$transaction(async tx=>{await tx.workAssignment.update({where:{id:assignment.id},data:{status:'IN_PROGRESS'}});return tx.workTimeEntry.create({data:{assignmentId:assignment.id,checkedInAt:new Date(),...location}})});res.status(201).json({entry});}));
app.post('/api/mzansiwork/assignments/:id/check-out',current,asyncRoute(async(req:any,res:any)=>{const assignment=await ownWorkerAssignment(req.params.id,req.identity.sub),entry=await db.workTimeEntry.findFirst({where:{assignmentId:assignment.id,checkedOutAt:null},orderBy:{checkedInAt:'desc'}});if(!entry)return res.status(409).json({error:'No active check-in exists'});const checkedOutAt=new Date(),minutes=workedMinutes(entry.checkedInAt,checkedOutAt);res.json({entry:await db.workTimeEntry.update({where:{id:entry.id},data:{checkedOutAt,minutes}}),minutes});}));
app.post('/api/mzansiwork/assignments/:id/complete',current,asyncRoute(async(req:any,res:any)=>{const assignment=await db.workAssignment.findUniqueOrThrow({where:{id:req.params.id},include:{job:true,timeEntries:true}});await ownEmployerJob(assignment.jobId,req.identity.sub);if(assignment.status!=='IN_PROGRESS'||assignment.timeEntries.some(e=>!e.checkedOutAt))return res.status(409).json({error:'Completed, closed time entries are required'});const minutes=assignment.timeEntries.reduce((sum,e)=>sum+(e.minutes||0),0),payment=expectedPayment(minutes,assignment.job.rateCents,assignment.job.rateUnit);res.json({assignment:await db.workAssignment.update({where:{id:assignment.id},data:{status:'COMPLETED',expectedPaymentCents:payment}}),minutes,expectedPaymentCents:payment});}));
