app.post('/api/supplier-orders',current,asyncRoute(async(req:any,res:any)=>{const input=supplierOrderSchema.parse(req.body);await requireBusiness(input.buyerId,req.identity.sub);const supplier=await db.supplierProfile.findUniqueOrThrow({where:{id:input.supplierId},include:{business:true}});if(supplier.verificationStatus!=='VERIFIED')return res.status(409).json({error:'Supplier is not verified'});const products=await db.supplierProduct.findMany({where:{id:{in:input.items.map(i=>i.productId)},supplierId:supplier.id,active:true}});if(products.length!==new Set(input.items.map(i=>i.productId)).size)return res.status(400).json({error:'Invalid supplier products'});const lines=input.items.map(item=>{const product=products.find(p=>p.id===item.productId)!;return{productId:product.id,productName:product.name,quantity:item.quantity,unitPriceCents:product.wholesalePriceCents,minimumQuantity:product.minimumQuantity,availableQuantity:product.availableQuantity}}),subtotalCents=orderTotal(lines);const order=await db.$transaction(async tx=>{for(const line of lines)await tx.supplierProduct.update({where:{id:line.productId},data:{availableQuantity:{decrement:line.quantity}}});return tx.supplierOrder.create({data:{buyerId:input.buyerId,supplierId:input.supplierId,deliveryAddress:input.deliveryAddress,subtotalCents,items:{create:lines.map(({minimumQuantity,availableQuantity,...line})=>line)}},include:{items:true}})});res.status(201).json({order});}));
app.post('/api/supplier-orders/:id/accept',current,asyncRoute(async(req:any,res:any)=>{const order=await db.supplierOrder.findUniqueOrThrow({where:{id:req.params.id},include:{supplier:{include:{business:true}},items:true}});await requireBusiness(order.supplier.businessId,req.identity.sub);if(order.status!=='PLACED')return res.status(409).json({error:'Order is not awaiting acceptance'});const result=await db.$transaction(async tx=>{const request=await tx.stockRequest.create({data:{businessId:order.buyerId,supplierName:order.supplier.business.name,deliveryAddress:order.deliveryAddress,status:'SEARCHING_DRIVER',estimatedTotalCents:order.subtotalCents,items:{create:order.items.map(i=>({productName:i.productName,quantity:i.quantity,estimatedUnitCents:i.unitPriceCents}))}}});return tx.supplierOrder.update({where:{id:order.id},data:{status:'READY_FOR_PICKUP',stockRequestId:request.id},include:{items:true,stockRequest:true}})});res.json({order:result});}));
