app.post('/api/subscriptions',current,asyncRoute(async(req:any,res:any)=>{const input=subscribeSchema.parse(req.body);await requireBusiness(input.businessId,req.identity.sub);const plan=await db.ecosystemPlan.findFirstOrThrow({where:{id:input.planId,active:true}}),subscription=await db.$transaction(async tx=>{const now=new Date(),created=await tx.ecosystemSubscription.create({data:{businessId:input.businessId,planId:plan.id,status:plan.priceCents===0?'ACTIVE':'PENDING_PAYMENT',priceCents:plan.priceCents,billingPeriod:plan.billingPeriod,featuresSnapshot:plan.features,limitsSnapshot:plan.limits,...(plan.priceCents===0?{currentPeriodFrom:now,currentPeriodTo:periodEnd(now,plan.billingPeriod)}:{})}});if(plan.priceCents===0)await tx.ecosystemSubscription.updateMany({where:{businessId:input.businessId,status:'ACTIVE',id:{not:created.id}},data:{status:'CANCELLED',cancelledAt:now}});else await tx.ecosystemInvoice.create({data:{subscriptionId:created.id,invoiceNumber:`HS-${Date.now()}-${Math.floor(Math.random()*10000)}`,amountCents:plan.priceCents,dueAt:new Date(Date.now()+7*86400000)}});await tx.auditLog.create({data:{action:'ECOSYSTEM_SUBSCRIPTION_CREATED',entity:'EcosystemSubscription',entityId:created.id,userId:req.identity.sub,metadata:JSON.stringify({businessId:input.businessId,planCode:plan.code,priceCents:plan.priceCents})}});return tx.ecosystemSubscription.findUniqueOrThrow({where:{id:created.id},include:{plan:true,invoices:true}})});res.status(201).json({subscription});}));
