app.post('/api/support/tickets',current,asyncRoute(async(req:any,res:any)=>{const input=supportTicketSchema.parse(req.body),context=input.contextType&&input.contextId?await resolveSupportContext(input.contextType,input.contextId,req.identity.sub):{partyIds:[req.identity.sub],record:null};const createdAt=new Date(),ticketNumber=`HYD-${createdAt.getUTCFullYear()}-${crypto.randomUUID().slice(0,8).toUpperCase()}`,slaDueAt=new Date(createdAt.getTime()+slaHours(input.priority)*3600000),partyIds=uniqueParticipants([req.identity.sub,...context.partyIds]);const ticket=await db.$transaction(async tx=>{const created=await tx.supportTicket.create({data:{ticketNumber,requesterId:req.identity.sub,category:input.category,priority:input.priority,subject:input.subject,description:input.description,isDispute:input.isDispute,contextType:input.contextType,contextId:input.contextId,slaDueAt,parties:{create:partyIds.map(userId=>({userId,role:userId===req.identity.sub?'REQUESTER':'TRANSACTION_PARTY'}))},evidence:{create:input.evidence.map(e=>({...e,uploadedBy:req.identity.sub}))},actions:{create:{actorId:req.identity.sub,action:'CREATED',toState:'OPEN',notes:input.isDispute?'Transaction dispute opened':'Support request opened'}}},include:{parties:true,evidence:true,actions:true}});const staff=await tx.user.findMany({where:{roles:{some:{role:{in:['STAFF','ADMIN','SUPER_ADMIN']}}}},select:{id:true}});await tx.conversation.create({data:{contextType:'SUPPORT_TICKET',contextId:created.id,subject:`${created.ticketNumber}: ${created.subject}`,participants:{create:uniqueParticipants([...partyIds,...staff.map(s=>s.id)]).map(userId=>({userId}))}}});return created});res.status(201).json({ticket});}));
