app.get('/api/admin/support/tickets',current,asyncRoute(async(req:any,res:any)=>{requireSupportStaff(req);const query=z.object({status:z.enum(['OPEN','ASSIGNED','WAITING','RESOLVED','CLOSED']).optional(),category:z.enum(['PAYMENTS','DELIVERY','DRIVER','STOCK','SERVICE_PROVIDER','EMPLOYMENT','ACCOUNT','VERIFICATION','TECHNICAL']).optional(),priority:z.enum(['LOW','NORMAL','HIGH','URGENT']).optional(),assigneeId:z.string().optional(),overdue:z.enum(['true','false']).optional()}).parse(req.query),where:any={...(query.status?{status:query.status}:{}),...(query.category?{category:query.category}:{}),...(query.priority?{priority:query.priority}:{}),...(query.assigneeId?{assigneeId:query.assigneeId}:{}),...(query.overdue==='true'?{slaDueAt:{lt:new Date()},status:{notIn:['RESOLVED','CLOSED']}}:{})};res.json({tickets:await db.supportTicket.findMany({where,include:{requester:{select:{id:true,firstName:true,lastName:true,email:true}},assignee:{select:{id:true,firstName:true,lastName:true}},parties:{include:{user:{select:{id:true,firstName:true,lastName:true}}}},_count:{select:{evidence:true,actions:true}}},orderBy:[{priority:'desc'},{slaDueAt:'asc'}]})});}));
