app.post('/api/admin/support/tickets/:id/assign',current,asyncRoute(async(req:any,res:any)=>{requireSupportStaff(req);const {assigneeId}=z.object({assigneeId:z.string().optional()}).parse(req.body),selected=assigneeId||req.identity.sub,assignee=await db.user.findFirst({where:{id:selected,roles:{some:{role:{in:['STAFF','ADMIN','SUPER_ADMIN']}}}}});if(!assignee)return res.status(400).json({error:'Assignee must be authorised support staff'});const ticket=await db.supportTicket.findUniqueOrThrow({where:{id:req.params.id}});if(ticket.status!=='ASSIGNED')assertSupportTransition(ticket.status,'ASSIGNED');const updated=await db.$transaction(async tx=>{await tx.supportAction.create({data:{ticketId:ticket.id,actorId:req.identity.sub,action:'ASSIGNED',fromState:ticket.status,toState:'ASSIGNED',notes:`Assignee: ${selected}`}});await tx.auditLog.create({data:{action:'SUPPORT_ASSIGNED',entity:'SupportTicket',entityId:ticket.id,userId:req.identity.sub,metadata:JSON.stringify({assigneeId:selected})}});return tx.supportTicket.update({where:{id:ticket.id},data:{assigneeId:selected,status:'ASSIGNED',firstResponseAt:ticket.firstResponseAt??new Date()}})});await notify(db,{userIds:[ticket.requesterId],event:'SUPPORT_REPLY',data:{ticketNumber:ticket.ticketNumber,status:'ASSIGNED'},relatedEntityType:'SupportTicket',relatedEntityId:ticket.id});res.json({ticket:updated});}));
app.post('/api/admin/support/tickets/:id/status',current,asyncRoute(async(req:any,res:any)=>{requireSupportStaff(req);const input=z.object({status:z.enum(['ASSIGNED','WAITING','RESOLVED','CLOSED']),notes:z.string().min(3).max(2000),resolution:z.string().min(3).max(2000).optional()}).parse(req.body),ticket=await db.supportTicket.findUniqueOrThrow({where:{id:req.params.id}});assertSupportTransition(ticket.status,input.status);if(input.status==='RESOLVED'&&!input.resolution)return res.status(400).json({error:'A resolution is required'});const now=new Date(),updated=await db.$transaction(async tx=>{await tx.supportAction.create({data:{ticketId:ticket.id,actorId:req.identity.sub,action:`STATUS_${input.status}`,fromState:ticket.status,toState:input.status,notes:input.notes}});await tx.auditLog.create({data:{action:`SUPPORT_STATUS_${input.status}`,entity:'SupportTicket',entityId:ticket.id,userId:req.identity.sub,metadata:JSON.stringify({from:ticket.status,notes:input.notes})}});return tx.supportTicket.update({where:{id:ticket.id},data:{status:input.status,resolution:input.resolution??ticket.resolution,resolvedAt:input.status==='RESOLVED'?now:ticket.resolvedAt,closedAt:input.status==='CLOSED'?now:null,firstResponseAt:ticket.firstResponseAt??now}})});await notify(db,{userIds:[ticket.requesterId],event:'SUPPORT_REPLY',data:{ticketNumber:ticket.ticketNumber,status:input.status},relatedEntityType:'SupportTicket',relatedEntityId:ticket.id});res.json({ticket:updated});}));
app.post('/api/admin/support/tickets/:id/financial-hold',current,asyncRoute(async(req:any,res:any)=>{requireSupportStaff(req);const {enabled,reason}=z.object({enabled:z.boolean(),reason:z.string().min(5).max(1000)}).parse(req.body),ticket=await db.supportTicket.findUniqueOrThrow({where:{id:req.params.id}});if(!ticket.isDispute||!ticket.contextId)return res.status(409).json({error:'Financial holds require a transaction-linked dispute'});const updated=await db.$transaction(async tx=>{await tx.supportAction.create({data:{ticketId:ticket.id,actorId:req.identity.sub,action:enabled?'FINANCIAL_HOLD_PLACED':'FINANCIAL_HOLD_RELEASED',notes:reason}});await tx.auditLog.create({data:{action:enabled?'SUPPORT_FINANCIAL_HOLD':'SUPPORT_FINANCIAL_RELEASE',entity:'SupportTicket',entityId:ticket.id,userId:req.identity.sub,metadata:JSON.stringify({contextType:ticket.contextType,contextId:ticket.contextId,reason})}});return tx.supportTicket.update({where:{id:ticket.id},data:{financialHold:enabled}})});res.json({ticket:updated});}));
app.post('/api/verifications',current,asyncRoute(async(req:any,res:any)=>{const input=verificationSubmissionSchema.parse(req.body);if(!await ownsVerificationTarget(input.type,input.targetId,req.identity.sub))return res.status(403).json({error:'Verification target ownership required'});const duplicate=await db.verificationCase.findFirst({where:{type:input.type,targetId:input.targetId,status:{in:['PENDING','UNDER_REVIEW','MORE_INFORMATION_REQUIRED']}}});if(duplicate)return res.status(409).json({error:'An active verification case already exists'});const verification=await db.verificationCase.create({data:{type:input.type,targetId:input.targetId,applicantId:req.identity.sub,documents:{create:input.documents},actions:{create:{actorId:req.identity.sub,decision:'SUBMITTED'}}},include:{documents:true,actions:true}});res.status(201).json({verification});}));
