app.post('/api/verifications/:id/resubmit',current,asyncRoute(async(req:any,res:any)=>{const currentCase=await db.verificationCase.findFirstOrThrow({where:{id:req.params.id,applicantId:req.identity.sub}});if(!['MORE_INFORMATION_REQUIRED','REJECTED'].includes(currentCase.status))return res.status(409).json({error:'Case is not eligible for resubmission'});assertVerificationTransition(currentCase.status,'PENDING');const {documents}=verificationSubmissionSchema.pick({documents:true}).parse(req.body),verification=await db.$transaction(async tx=>{await tx.verificationDocument.deleteMany({where:{caseId:currentCase.id}});await tx.verificationDocument.createMany({data:documents.map(d=>({...d,caseId:currentCase.id}))});await tx.verificationAction.create({data:{caseId:currentCase.id,actorId:req.identity.sub,decision:'RESUBMITTED'}});return tx.verificationCase.update({where:{id:currentCase.id},data:{status:'PENDING',reviewerId:null,reviewedAt:null,submittedAt:new Date()},include:{documents:true,actions:true}})});res.json({verification});}));
app.get('/api/admin/verifications',current,asyncRoute(async(req:any,res:any)=>{if(!req.identity.roles.some((r:string)=>['STAFF','ADMIN','SUPER_ADMIN'].includes(r)))return res.status(403).json({error:'Verification staff role required'});const query=z.object({type:z.enum(['PERSON','BUSINESS','DRIVER','SERVICE_PROVIDER','SUPPLIER','WORKER']).optional(),status:z.enum(['PENDING','UNDER_REVIEW','MORE_INFORMATION_REQUIRED','APPROVED','REJECTED']).optional()}).parse(req.query);res.json({verifications:await db.verificationCase.findMany({where:query,include:{applicant:{select:{id:true,firstName:true,lastName:true,email:true}},reviewer:{select:{id:true,firstName:true,lastName:true}},documents:true,actions:{orderBy:{createdAt:'asc'}}},orderBy:{submittedAt:'asc'}})});}));
app.post('/api/admin/verifications/:id/assign',current,asyncRoute(async(req:any,res:any)=>{if(!req.identity.roles.some((r:string)=>['STAFF','ADMIN','SUPER_ADMIN'].includes(r)))return res.status(403).json({error:'Verification staff role required'});const {reviewerId}=z.object({reviewerId:z.string().optional()}).parse(req.body),selected=reviewerId||req.identity.sub,reviewer=await db.user.findFirst({where:{id:selected,roles:{some:{role:{in:['STAFF','ADMIN','SUPER_ADMIN']}}}}});if(!reviewer)return res.status(400).json({error:'Reviewer must be authorised staff'});const verification=await db.verificationCase.findUniqueOrThrow({where:{id:req.params.id}});assertVerificationTransition(verification.status,'UNDER_REVIEW');const updated=await db.$transaction(async tx=>{await tx.verificationAction.create({data:{caseId:verification.id,actorId:req.identity.sub,decision:'ASSIGNED',reason:`Reviewer: ${selected}`}});return tx.verificationCase.update({where:{id:verification.id},data:{status:'UNDER_REVIEW',reviewerId:selected}})});res.json({verification:updated});}));
app.post('/api/admin/verifications/:id/decision',current,asyncRoute(async(req:any,res:any)=>{if(!req.identity.roles.some((r:string)=>['STAFF','ADMIN','SUPER_ADMIN'].includes(r)))return res.status(403).json({error:'Verification staff role required'});const input=verificationDecisionSchema.parse(req.body),verification=await db.verificationCase.findUniqueOrThrow({where:{id:req.params.id}});if(verification.reviewerId!==req.identity.sub&&!req.identity.roles.includes('SUPER_ADMIN'))return res.status(403).json({error:'Assigned reviewer or super administrator required'});const next=input.decision==='REQUEST_MORE_INFORMATION'?'MORE_INFORMATION_REQUIRED':input.decision;assertVerificationTransition(verification.status,next);const updated=await db.$transaction(async tx=>{await updateVerificationTarget(tx,verification.type,verification.targetId,input.decision);await tx.verificationAction.create({data:{caseId:verification.id,actorId:req.identity.sub,decision:input.decision,reason:input.reason}});await tx.auditLog.create({data:{action:`VERIFICATION_${input.decision}`,entity:'VerificationCase',entityId:verification.id,userId:req.identity.sub,metadata:JSON.stringify({type:verification.type,targetId:verification.targetId,reason:input.reason})}});return tx.verificationCase.update({where:{id:verification.id},data:{status:next,reviewedAt:new Date()}})});await notify(db,{userIds:[verification.applicantId],event:'VERIFICATION_UPDATE',data:{status:next},relatedEntityType:'VerificationCase',relatedEntityId:verification.id});res.json({verification:updated});}));
async function ownsVerificationTarget(type:string,targetId:string,userId:string){if(type==='PERSON')return targetId===userId;if(type==='BUSINESS')return Boolean(await db.businessMember.findUnique({where:{businessId_userId:{businessId:targetId,userId}}}));if(type==='DRIVER')return Boolean(await db.driverProfile.findFirst({where:{id:targetId,userId}}));if(type==='SERVICE_PROVIDER')return Boolean(await db.serviceProvider.findFirst({where:{id:targetId,userId}}));if(type==='SUPPLIER')return Boolean(await db.supplierProfile.findFirst({where:{id:targetId,business:{members:{some:{userId}}}}}));if(type==='WORKER')return Boolean(await db.workerProfile.findFirst({where:{id:targetId,userId}}));return false}
async function updateVerificationTarget(tx:any,type:string,targetId:string,decision:string){const status=decision==='APPROVED'?'VERIFIED':decision==='REJECTED'?'REJECTED':'UNDER_REVIEW';if(type==='BUSINESS')await tx.business.update({where:{id:targetId},data:{verificationStatus:status}});if(type==='DRIVER')await tx.driverProfile.update({where:{id:targetId},data:{verificationStatus:status}});if(type==='SERVICE_PROVIDER')await tx.serviceProvider.update({where:{id:targetId},data:{verificationStatus:status}});if(type==='SUPPLIER')await tx.supplierProfile.update({where:{id:targetId},data:{verificationStatus:status}});if(type==='WORKER')await tx.workerProfile.update({where:{id:targetId},data:{verificationStatus:status}})}
async function requireConversation(id:string,userId:string){const conversation=await db.conversation.findFirst({where:{id,participants:{some:{userId}}}});if(!conversation)throw Object.assign(new Error('Conversation not found'),{status:404});return conversation}
async function resolveConversationParticipants(type:string,id:string):Promise<string[]>{if(type==='DELIVERY'){const row=await db.stockRequest.findUniqueOrThrow({where:{id},include:{business:{include:{members:true}}}});return[...(row.driverId?[row.driverId]:[]),...row.business.members.map(m=>m.userId)]}if(type==='SERVICE_REQUEST'){const row=await db.serviceRequest.findUniqueOrThrow({where:{id},include:{provider:true}});return[row.customerId,...(row.provider?[row.provider.userId]:[])]}if(type==='JOB'){const row=await db.workAssignment.findUniqueOrThrow({where:{id},include:{worker:true,job:{include:{business:{include:{members:true}}}}}});return[row.worker.userId,...row.job.business.members.map(m=>m.userId)]}if(type==='SUPPLIER_ORDER'){const row=await db.supplierOrder.findUniqueOrThrow({where:{id},include:{buyer:{include:{members:true}},supplier:{include:{business:{include:{members:true}}}}}});return[...row.buyer.members.map(m=>m.userId),...row.supplier.business.members.map(m=>m.userId)]}if(type==='HOSTING_REQUEST'){const row=await db.hostingServiceRequest.findUniqueOrThrow({where:{id},include:{business:{include:{members:true}}}}),staff=await db.user.findMany({where:{roles:{some:{role:{in:['STAFF','ADMIN','SUPER_ADMIN']}}}},select:{id:true}});return[...row.business.members.map(m=>m.userId),...staff.map(s=>s.id)]}if(type==='SUPPORT_TICKET'){const ticket=await db.supportTicket.findUniqueOrThrow({where:{id},include:{parties:true}}),staff=await db.user.findMany({where:{roles:{some:{role:{in:['STAFF','ADMIN','SUPER_ADMIN']}}}},select:{id:true}});return uniqueParticipants([ticket.requesterId,...ticket.parties.map(p=>p.userId),...(ticket.assigneeId?[ticket.assigneeId]:[]),...staff.map(s=>s.id)])}throw Object.assign(new Error('Unsupported conversation context'),{status:400})}
function requireSupportStaff(req:any){if(!req.identity.roles.some((role:string)=>['STAFF','ADMIN','SUPER_ADMIN'].includes(role)))throw Object.assign(new Error('Support staff role required'),{status:403})}
async function resolveSupportContext(type:string,id:string,userId:string,staff=false):Promise<{partyIds:string[],record:any}>{let partyIds:string[]=[],record:any=null;if(type==='StockRequest'){record=await db.stockRequest.findUnique({where:{id},include:{business:{include:{members:true}},items:true}});if(record)partyIds=[...record.business.members.map((m:any)=>m.userId),...(record.driverId?[record.driverId]:[])]}else if(type==='ServiceRequest'){record=await db.serviceRequest.findUnique({where:{id},include:{provider:true,quotes:true,transitions:true}});if(record)partyIds=[record.customerId,...(record.provider?[record.provider.userId]:[])]}else if(type==='WorkAssignment'){record=await db.workAssignment.findUnique({where:{id},include:{worker:true,job:{include:{business:{include:{members:true}}}},timeEntries:true}});if(record)partyIds=[record.worker.userId,...record.job.business.members.map((m:any)=>m.userId)]}else if(type==='SupplierOrder'){record=await db.supplierOrder.findUnique({where:{id},include:{buyer:{include:{members:true}},supplier:{include:{business:{include:{members:true}}}},items:true}});if(record)partyIds=[...record.buyer.members.map((m:any)=>m.userId),...record.supplier.business.members.map((m:any)=>m.userId)]}else if(type==='HostingSubscription'){record=await db.hostingSubscription.findUnique({where:{id},include:{business:{include:{members:true}},plan:true,invoices:true,domains:true,mailboxes:true}});if(record)partyIds=record.business.members.map((m:any)=>m.userId)}else if(type==='VerificationCase'){record=await db.verificationCase.findUnique({where:{id},include:{documents:true,actions:true}});if(record)partyIds=[record.applicantId,...(record.reviewerId?[record.reviewerId]:[])]}else if(type==='PaymentRecord'){record=await db.paymentRecord.findUnique({where:{id}});if(record){let metadata:any={};try{metadata=record.metadata?JSON.parse(record.metadata):{}}catch{}partyIds=[metadata.userId,metadata.customerId].filter(Boolean);if(metadata.businessId){const members=await db.businessMember.findMany({where:{businessId:metadata.businessId},select:{userId:true}});partyIds.push(...members.map(m=>m.userId))}if(record.relatedEntityType&&record.relatedEntityId&&record.relatedEntityType!=='PaymentRecord'){try{const related=await resolveSupportContext(record.relatedEntityType,record.relatedEntityId,userId,staff);partyIds.push(...related.partyIds)}catch{}}}}else throw Object.assign(new Error('Unsupported support context'),{status:400});if(!record)throw Object.assign(new Error('Referenced transaction was not found'),{status:404});partyIds=uniqueParticipants(partyIds);if(!staff&&!partyIds.includes(userId))throw Object.assign(new Error('Only transaction participants may open this case'),{status:403});return{partyIds,record}}
async function ownSupplier(id:string,userId:string){const supplier=await db.supplierProfile.findFirst({where:{id,business:{members:{some:{userId}}}}});if(!supplier)throw Object.assign(new Error('Supplier access required'),{status:403});return supplier}
async function ownEmployerJob(id:string,userId:string){const job=await db.jobPost.findFirst({where:{id,business:{members:{some:{userId}}}}});if(!job)throw Object.assign(new Error('Employer job not found'),{status:404});return job}
async function ownWorkerAssignment(id:string,userId:string){const assignment=await db.workAssignment.findFirst({where:{id,worker:{userId}},include:{job:true,timeEntries:true}});if(!assignment)throw Object.assign(new Error('Worker assignment not found'),{status:404});return assignment}
async function ownServiceCustomer(id:string,userId:string){const request=await db.serviceRequest.findFirst({where:{id,customerId:userId}});if(!request)throw Object.assign(new Error('Customer request not found'),{status:404});return request}
async function transitionService(request:any,toState:any,actorId:string){return db.$transaction(async tx=>{const updated=await tx.serviceRequest.update({where:{id:request.id},data:{status:toState}});await tx.serviceTransition.create({data:{requestId:request.id,fromState:request.status,toState,actorId}});return updated})}
async function activateEcosystemSubscription(tx:any,id:string){const subscription=await tx.ecosystemSubscription.findUniqueOrThrow({where:{id}}),now=new Date();await tx.ecosystemSubscription.updateMany({where:{businessId:subscription.businessId,status:'ACTIVE',id:{not:id}},data:{status:'CANCELLED',cancelledAt:now}});return tx.ecosystemSubscription.update({where:{id},data:{status:'ACTIVE',currentPeriodFrom:now,currentPeriodTo:periodEnd(now,subscription.billingPeriod)}})}
async function requireBusiness(businessId:string,userId:string){const member=await db.businessMember.findUnique({where:{businessId_userId:{businessId,userId}}});if(!member)throw Object.assign(new Error('Business access required'),{status:403});return member}
async function ownDriverRequest(id:string,userId:string){const request=await db.stockRequest.findFirst({where:{id,driverId:userId},include:{items:true}});if(!request)throw Object.assign(new Error('Assigned request not found'),{status:404});return request}
async function ownBusinessRequest(id:string,userId:string){const request=await db.stockRequest.findFirst({where:{id,business:{members:{some:{userId}}}},include:{items:true}});if(!request)throw Object.assign(new Error('Business request not found'),{status:404});return request}
function safe(u:any){return{id:u.id,email:u.email,phone:u.phone,firstName:u.firstName,lastName:u.lastName,status:u.status};}
const publicDir=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'public');app.use(express.static(publicDir));app.use((_req,res)=>res.sendFile(path.join(publicDir,'index.html')));
app.use((err:any,_req:any,res:any,_next:any)=>{console.error(err);if(err?.name==='ZodError')return res.status(400).json({error:'Please check the submitted fields',details:err.issues});res.status(err?.status||500).json({error:err?.status?err.message:'Unexpected server error'});});
if(process.env.NODE_ENV!=='test')app.listen(Number(process.env.PORT||3000),()=>console.log(`HYDRA CORE running on ${process.env.PORT||3000}`));
export {app};
